CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('admin','user')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS donations(id BIGSERIAL PRIMARY KEY,donor_name TEXT NOT NULL,mobile TEXT,amount NUMERIC(12,2) NOT NULL CHECK(amount>=0),payment_mode TEXT,donation_for TEXT,remarks TEXT,donated_at DATE NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses(id BIGSERIAL PRIMARY KEY,expense_head TEXT NOT NULL,description TEXT,amount NUMERIC(12,2) NOT NULL CHECK(amount>=0),payment_mode TEXT,paid_by TEXT,bill_reference TEXT,remarks TEXT,spent_at DATE NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS budgets(id BIGSERIAL PRIMARY KEY,budget_head TEXT NOT NULL,allocated_amount NUMERIC(12,2) NOT NULL CHECK(allocated_amount>=0),remarks TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS transaction_log(id BIGSERIAL PRIMARY KEY,transaction_date DATE NOT NULL,transaction_type TEXT NOT NULL CHECK(transaction_type IN ('Donation','Expense')),amount NUMERIC(12,2) NOT NULL,description TEXT,payment_mode TEXT,reference_id TEXT,remarks TEXT,source_id BIGINT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,filename TEXT NOT NULL,stored_name TEXT NOT NULL,uploaded_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_donations_date ON donations(donated_at DESC); CREATE INDEX IF NOT EXISTS idx_expenses_date ON expenses(spent_at DESC); CREATE INDEX IF NOT EXISTS idx_transactions_date ON transaction_log(transaction_date DESC); 
